package coreurl

type urlRequestSpec struct {
	URL     string
	Headers map[string]string
}
type urlRuleCase struct {
	operation       string
	first           string
	second          string
	config          any
	request         *urlRequestSpec
	path            string
	pathSet         bool
	loadEnvironment *bool
	trusted         bool
	wantString      *string
	wantBool        *bool
	wantError       string
}

func urlRuleBool(value bool) *bool       { return &value }
func urlRuleString(value string) *string { return &value }

